import java.util.Scanner;
public class JIfElseIfGrade1 {
	public static void main(String[] args) {
		//Khatwa 1: qiraat al-daraja
		Scanner scan = new Scanner (System.in);
		System.out.println("Adkhul daraja: "); 
		int score = scan.nextInt();
		scan.close();
		//Khatwa 2: tahdeed al-daraja lildaraja
		String grade;
		if (score >= 90) {
			grade = "A";
		} else if (score >= 80) {
			grade = "B";
		} else if (score >= 70) {
			grade = "C";
		} else if (score >= 60) {
			grade = "D";
		} else {
			grade = "F";
		}
		//Khatwa 3: atba3 al-daraja
		System.out.println("Daraja = " + grade);	
	}
}
